package fx.drv;

import fx.stub.StubConnection;
import fx.trace.Ran;
import java.sql.DatabaseMetaData;
import java.sql.PreparedStatement;

public final class FxConnection extends StubConnection {
    private boolean autoCommit = true;
    @Override public PreparedStatement prepareStatement(String sql) { Ran.stack(); return new FxStatement(this); }
    @Override public PreparedStatement prepareStatement(String sql, int type, int concurrency) { Ran.stack(); return new FxStatement(this); }
    @Override public PreparedStatement prepareStatement(String sql, int autoGeneratedKeys) { Ran.stack(); return new FxStatement(this); }
    @Override public boolean getAutoCommit() { return autoCommit; }
    @Override public void setAutoCommit(boolean b) { autoCommit = b; }
    @Override public DatabaseMetaData getMetaData() { return new FxDatabaseMetaData(); }
    @Override public void close() { Ran.stack(); }
}
